<?php declare(strict_types=1);
try{
    $selected=input($_GET,'balance_source');[$sourceType,$sourceId]=array_pad(explode(':',$selected,2),2,'');$revision=input($_GET,'source_original');if(!preg_match('/\A[1-9][0-9]{0,3}\z/D',$revision))throw new DomainException('Ursprünglichen Belegvorgang nicht gefunden.',404);
    $annualOriginal=$annualSourceLedger->sourceDecisionOriginal($sourceType,$sourceId,(int)$revision,input($_GET,'source_original_sha256'));$annualContext=$annualOriginal['context'];$annualRequest=$annualContext['request'];$annualYear=$annualRequest['year'];$annualCurrent=null;
    try{$annualCurrent=$annualSourceLedger->report($annualYear);}catch(DomainException){/* Do not replace a retained original by a live stand. */}
}catch(DomainException $ex){if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,409,422,503],true)?$ex->getCode():403);echo '<p role="alert">'.e($annualSourceText($ex->getMessage())).'</p>';return;}
$annualMoney=static fn(int $cents):string=>number_format($cents/100,2,',','.').' €';$annualDate=static fn(string $date):string=>implode('.',array_reverse(explode('-',$date)));$annualAt=(new DateTimeImmutable($annualOriginal['payload']['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i');$annualLabels=[];foreach($annualContext['targets']as$target)$annualLabels[$target['type'].':'.$target['id']]=$target['label'];$annualHome=['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$annualYear];
?>
<link rel="stylesheet" href="tax-guided.css?v=3"><div class="content" data-tax-guided>
<div class="page-heading"><h1><?= e($annualSourceText('Ausgang der Belegübernahme')) ?></h1></div><p><?= e((string)$annualYear) ?></p>
<section class="card" data-annual-source-outcome="<?= e($annualOriginal['sha256']) ?>" data-annual-source-revision="<?= $annualOriginal['revision'] ?>">
<p role="status"><strong><?= e($annualSourceText($annualRequest['operation']==='correct'?'Belegübernahme berichtigt':'Beleg übernommen')) ?></strong></p><p><?= e($annualSourceText('Dies ist der damals gespeicherte Vorgang. Eine Wiederaufnahme erzeugt keine weitere Buchung und keine neue Freigabe.')) ?></p>
<h2 data-annual-source-description><?= e($annualContext['source_label']['description']) ?></h2><?php if($annualOriginal['type']==='invoice'): ?><p><a class="btn btn-outline" data-annual-source-invoice-original href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$annualOriginal['id']])) ?>"><?= e($annualSourceText('Originalrechnung öffnen')) ?></a></p><?php endif ?><?php foreach(['account_name','counterparty']as$key)if($annualContext['source_label'][$key]!==''): ?><p><?= e($annualContext['source_label'][$key]) ?></p><?php endif ?>
<dl><?php if($annualOriginal['type']==='invoice'): ?><dt><?= e($annualSourceText(($annualOriginal['payload']['proposal']['snapshot']['entry']['kind']??'')==='contribution'?'Beitragsforderung entstanden am':'Leistung oder Lieferung am')) ?></dt><dd data-annual-source-recognised-on><?= e($annualDate($annualRequest['options']['recognised_on'])) ?></dd><?php if(($annualRequest['options']['private_paid_on']??'')!==''): ?><dt><?= e($annualSourceText('Vom Mitglied bezahlt am')) ?></dt><dd><?= e($annualDate($annualRequest['options']['private_paid_on'])) ?></dd><?php endif;elseif($annualOriginal['type']==='transaction'): ?><dt><?= e($annualSourceText('Buchungsdatum')) ?></dt><dd data-annual-source-booked-on><?= e($annualDate($annualOriginal['payload']['proposal']['snapshot']['transaction']['booked_on'])) ?></dd><?php endif ?><dt><?= e($annualSourceText('Damals angenommen am')) ?></dt><dd><?= e($annualAt) ?></dd><dt><?= e($annualSourceText('Ergebnis dieses Zeitraums')) ?></dt><dd data-annual-source-result><?= e($annualMoney($annualContext['result']['annual_result_cents'])) ?></dd><dt><?= e($annualSourceText('Vermögen am Ende')) ?></dt><dd><?= e($annualMoney($annualContext['result']['asset_total_cents'])) ?></dd><?php if($annualRequest['reason']!==''): ?><dt><?= e($annualSourceText('Grund der Korrektur')) ?></dt><dd data-annual-source-reason><?= e($annualRequest['reason']) ?></dd><?php endif ?></dl>
<details data-annual-source-original-postings><summary><?= e($annualSourceText('Damals gespeicherte Buchungen und Gegenbuchungen')) ?></summary>
<?php foreach($annualOriginal['items']as$annualItem):$annualProposal=$annualItem['payload']['proposal'];$annualOld=null;if($annualItem['revision']>1){$annualBinding=(new \Kulturhus\Verein\BalanceSources($db,(string)$_SESSION['actor']))->binding($annualItem['type'],$annualItem['id']);$annualHistory=(new \Kulturhus\Verein\BalanceSourceHistory($db,(string)$_SESSION['actor']))->checked($annualBinding);$annualOld=$annualHistory[$annualItem['revision']-2]['payload']['proposal'];} ?>
<article data-annual-source-original="<?= e($annualItem['sha256']) ?>">
<?php $annualLabel=$annualLabels[$annualItem['type'].':'.$annualItem['id']]; ?><h3><?= e($annualLabel['description']) ?></h3><?php if($annualLabel['account_name']!==''): ?><p><?= e($annualLabel['account_name']) ?></p><?php endif ?>
<?php foreach(['reversal'=>$annualOld,'posting'=>$annualProposal]as$annualKind=>$annualShown)if($annualShown!==null): ?><h3><?= e($annualSourceText($annualKind==='reversal'?'Gegenbuchungen':'Buchungen')) ?></h3><?php foreach($annualShown['vouchers']as$annualVoucher): ?><p><?= e($annualDate($annualVoucher['date']).' · '.(!empty($annualShown['snapshot']['internal_movements'])?$annualSourceText($annualVoucher['description']):$annualVoucher['description'])) ?></p><dl><?php foreach($annualVoucher['lines']as$annualLine):$annualDebit=$annualKind==='reversal'?$annualLine['credit_cents']:$annualLine['debit_cents'];$annualCredit=$annualKind==='reversal'?$annualLine['debit_cents']:$annualLine['credit_cents']; ?><dt><?= e($annualShown['accounts'][$annualLine['account']]['name']) ?></dt><dd><?= e($annualSourceText('Soll').' '.$annualMoney($annualDebit).' · '.$annualSourceText('Haben').' '.$annualMoney($annualCredit)) ?></dd><?php endforeach ?></dl><?php endforeach ?><?php endif ?>
<?php if($annualProposal['type']==='transaction'):$annualTransaction=$annualProposal['snapshot']['transaction']; ?><p><a class="btn btn-outline text-wrap" data-annual-source-bank-original href="<?= e(url(['view'=>'finance','tab'=>'bank','account'=>$annualTransaction['account_id'],'transaction'=>$annualTransaction['id']])) ?>"><?= e($annualSourceText('Ursprünglichen Kontoumsatz im Bankbereich öffnen')) ?></a></p><?php endif ?>
<?php if(!empty($annualProposal['snapshot']['internal_movements'])){$preview=$annualProposal;require __DIR__.'/balance-own-movements.php';} ?>
</article><?php endforeach ?></details></section>
<?php if($annualCurrent!==null): ?><section class="card" data-annual-source-current><h2><?= e($annualSourceText('Aktueller Jahresstand')) ?></h2><p><?= e($annualSourceText($annualCurrent['state']==='closed'?'Buchungsstand festgeschrieben':($annualCurrent['state']==='setup'?'Anfangsbestände prüfen':'Buchungsstand offen'))) ?></p><p><?= e($annualSourceText('Ergebnis dieses Zeitraums').': '.$annualMoney($annualCurrent['calculation']['annual_result_cents'])) ?></p><p data-annual-source-current-assets><?= e($annualSourceText('Vermögen am Ende').': '.$annualMoney($annualCurrent['calculation']['asset_total_cents'])) ?></p></section><?php endif ?>
<p><a class="btn btn-outline" href="<?= e(url($annualHome)) ?>"><?= e($annualSourceText('Aktuellen Jahresstand öffnen')) ?></a> <a class="btn btn-outline text-wrap" data-annual-source-selection href="<?= e(url($annualHome+['balance_source'=>$annualOriginal['type'].':'.$annualOriginal['id']])) ?>"><?= e($annualSourceText('Aktuellen Beleg und seine Zuordnung prüfen')) ?></a></p>
</div>
